from decimal import Decimal

import pytest
from hypothesis import given
from hypothesis import strategies as st

from refproj.pricing import format_price, parse_price

# Every price from 0.00 to 9,999,999.99 in whole cents, drawn as a count of cents. The same
# price is also drawn the way the contract writes its own examples (`Decimal("12.5")`,
# `Decimal("0")`): without the trailing zeros.
_CENTS = st.integers(min_value=0, max_value=999_999_999)
_TWO_PLACES = _CENTS.map(lambda cents: Decimal(cents).scaleb(-2))
PRICES = st.one_of(_TWO_PLACES, _TWO_PLACES.map(lambda price: price.normalize()))


def test_format_always_prints_two_decimals() -> None:
    assert format_price(Decimal("12.5")) == "12.50"


