from refproj.pricing import format_price, parse_price

# Every price from 0.00 to 9,999,999.99 in whole cents, in each way a Decimal can spell it:
# "12.50", "12.5" and "12.500" are the same price.
_SPELLINGS = (
    lambda price: price,
    lambda price: price.normalize(),
    lambda price: price.quantize(Decimal("0.001")),
)
PRICES = st.builds(
    lambda cents, spell: spell(Decimal(cents).scaleb(-2)),
    st.integers(min_value=0, max_value=999_999_999),
    st.sampled_from(_SPELLINGS),
)


