def test_format_rejects_a_fraction_of_a_cent_instead_of_rounding() -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(Decimal("12.345"))


def test_parse_reads_the_printed_text() -> None:
    assert parse_price("1,234.50") == Decimal("1234.50")


def test_parse_reads_the_text_with_commas_left_out() -> None:
    assert parse_price("1234.50") == Decimal("1234.50")


@pytest.mark.parametrize(
    ("text", "printed"),
    [
        ("1,234.50", "1234.50"),
