def test_parse_rejects_currency_signs_and_other_separators(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@pytest.mark.parametrize("text", ["10,000,000.00", "10000000.00", "-1.00"])
def test_parse_rejects_text_outside_the_price_range(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@given(PRICES)
def test_I1_printed_price_reads_back_as_the_same_price(price: Decimal) -> None:
